// Fisher-Yates shuffle for unbiased random selection
function fisherYates(arr: any[]) {
  const shuffled = [...arr];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export function getRandomProducts(count: number): AmazonProduct[] {
  if (count >= AMAZON_PRODUCTS.length) return AMAZON_PRODUCTS;
  return fisherYates(AMAZON_PRODUCTS).slice(0, count);
}

export function getRandomProductsExcluding(count: number, exclude: string[] = []): AmazonProduct[] {
  const filtered = AMAZON_PRODUCTS.filter(p => !exclude.includes(p.asin));
  if (count >= filtered.length) return filtered;
  return fisherYates(filtered).slice(0, count);
}
